/* Validated primary/backup story records. Unknown gameplay fields survive migration. */
const STORY_KEY='spare-room-halloween-v1',STORY_BACKUP=STORY_KEY+'-backup';
function validateStory(value){if(!value||typeof value!=='object'||Array.isArray(value))return null;if(!Number.isInteger(value.day)||value.day<1||value.day>3||typeof value.room!=='string'||!Number.isFinite(value.memory)||!Number.isFinite(value.unease))return null;for(const k of ['inventory','seen','history'])if(!Array.isArray(value[k]))return null;if(!value.inventory.every(x=>typeof x==='string')||!value.seen.every(x=>typeof x==='string')||!value.history.every(x=>typeof x==='boolean'))return null;if(value.sanity!==undefined&&(!Number.isFinite(value.sanity)||value.sanity<0||value.sanity>100))return null;if(value.ending!==null&&value.ending!==undefined&&(typeof value.ending.title!=='string'||typeof value.ending.body!=='string'))return null;
 const copy={...value};if(copy.wallSecrets){const w=copy.wallSecrets;if(w.schema!==1||!Array.isArray(w.found)||!Array.isArray(w.achievements)||!w.found.every(x=>typeof x==='string')||!w.achievements.every(x=>typeof x==='string'))delete copy.wallSecrets;else copy.wallSecrets={...w,found:[...new Set(w.found)],achievements:[...new Set(w.achievements)],visits:Number.isSafeInteger(w.visits)&&w.visits>=0?w.visits:0};}return copy;}
function readStoryRecord(key){try{const text=localStorage.getItem(key);if(!text||text.length>2000000)return null;return validateStory(JSON.parse(text));}catch{return null;}}
function loadStorySave(fallback){return readStoryRecord(STORY_KEY)||readStoryRecord(STORY_BACKUP)||fallback();}
let storyLastSaved=null,storySaveFailed=false;
function persistStorySave(value){const clean=validateStory(value);if(!clean)return false;try{const text=JSON.stringify(clean);if(text===storyLastSaved)return true;const old=readStoryRecord(STORY_KEY);if(old)localStorage.setItem(STORY_BACKUP,JSON.stringify(old));localStorage.setItem(STORY_KEY,text);storyLastSaved=text;storySaveFailed=false;return true;}catch{storySaveFailed=true;return false;}}
